function servicetask418(attempt, message) {

	log.info("INICIANDO SERVICE TASK DE ATUALIZACAO DE VALOR DO RPS GERADO")

	var codColigada = hAPI.getCardValue("CodColigada");
	var codFilial = hAPI.getCardValue("filial");
	var idmovMovimento02 = hAPI.getCardValue("historico2102").split(",").pop().trim();
	var valorAlterado = hAPI.getCardValue("valorAlterado").trim();

	if (valorAlterado == null || valorAlterado == undefined || valorAlterado == "") return

	log.info("INFO DE VALOR NAO NULA PARA O RPS, EXECUTANDO INTEGRACAO COM RM ")


	var usuario_rm = getConstante("rm_usuario");
	var senha_rm = getConstante("rm_senha");

	log.info("CODCOLIGADA: " + codColigada + " | CODFILIAL: " + codFilial);

	try { /* */ var servico = ServiceManager.getService("wsDataServer");
		var instancia = servico.instantiate("com.totvs.WsDataServer");
		var ws = instancia.getRMIwsDataServer();
		var properties = {};
		properties['basic.authorization'] = 'true';
		properties['basic.authorization.username'] = usuario_rm;
		properties['basic.authorization.password'] = senha_rm;
		properties['disable.chunking'] = 'true';
		properties['log.soap.messages'] = 'true';
		properties['receive.timeout'] = '180000';

		var authService = servico.getCustomClient(ws, properties, []);

		var contexto = "CODCOLIGADA=" + codColigada + ";CODFILIAL=" + codFilial + ";CODSISTEMA=T;CODUSUARIO=fluig";

		log.info("### Servico OK, executando atualização de valor do RPS");

		var xml =
			"<MovMovimento>" +
			"<TMOV>" +
			"<CODCOLIGADA>" + codColigada + "</CODCOLIGADA>" +
			"<IDMOV>" + idmovMovimento02 + "</IDMOV>" +
			"<INTEGRAAPLICACAO>T</INTEGRAAPLICACAO>" +
			"</TMOV>" +
			"<TITMMOV>" +
			"<CODCOLIGADA>" + codColigada + "</CODCOLIGADA>" +
			"<IDMOV>" + idmovMovimento02 + "</IDMOV>" +
			"<NSEQITMMOV>1</NSEQITMMOV>" +
			"<NUMEROSEQUENCIAL>1</NUMEROSEQUENCIAL>" +
			"<PRECOUNITARIO>" + valorAlterado + "</PRECOUNITARIO>" +
			"</TITMMOV>" +
			"</MovMovimento>";

		var resultado = authService.saveRecord("MOVMOVIMENTOTBCDATA", xml, contexto);

		log.info("G12-AJUSTAR-RPS  -> Resultado " + ": " + resultado);

	} catch (error) {
		log.error("ERRO AO JUSTAR RPS:  " + error)
		throw ("ERRO AO JUSTAR RPS:  " + error);
	}

	try {

		var c1 = DatasetFactory.createConstraint("CODCOLIGADA", codColigada, codColigada, ConstraintType.MUST);
		var c2 = DatasetFactory.createConstraint("IDMOV", idmovMovimento02, idmovMovimento02, ConstraintType.MUST);

		var datasetTributos = DatasetFactory.getDataset("G12-CARREGAR-TRIBUTOS", null, [c1, c2], null);

		if (datasetTributos == null || datasetTributos.rowsCount == 0) {
			log.warn("[G12-AJUSTAR-RPS] Nenhum tributo retornado apos atualizacao do valor. CodColigada=" + codColigada + " IdMov2=" + idmovMovimento02);
			return;
		}

		hAPI.setCardValue('tributosNacionais', safe(datasetTributos.getValue(0, "TRIBUTOS_NACIONAIS")));

		log.info("TRIBUTOS NACIONAIS ATUALIZADOS APOS AJUSTE DO VALOR DO RPS -> " + datasetTributos.getValue(0, "TRIBUTOS_NACIONAIS"));

	} catch (error) {
		log.error("### Erro ao recarregar tributos nacionais apos ajuste do valor do RPS -> " + error);
		throw error;
	}

}

function servicetask78(attempt, message) {
    /**
     * AUTHOR: ENOS DESENVOLVEDOR FLUIG/FULL STACK 
     * CRIADO EM: 29/05/2026
     * PROPOSITO: FATURAR OS MOVIMENTOS DE VENDAS DO TIPO 2.1.02 , CRIAR MOVIMENTO 2.2.01 E GERAR O RELACIONAMENTO ENTRE ELES DENTRO DO RM 
    */



    var codColigada = hAPI.getCardValue("CodColigada");
    var idMov = hAPI.getCardValue("idmov2");
    var codFilial = hAPI.getCardValue("filial");
    var codigoExercicioFiscal = hAPI.getCardValue("exercicioFiscal");
    var today = new java.text.SimpleDateFormat("yyyy-MM-dd").format(new java.util.Date());

    var usuario_rm = getConstante("rm_usuario");
    var senha_rm = getConstante("rm_senha");

    try {

        /* 
        AQUI VAI ACONTECER A MÁGICA DA INTEGRACAO 
        1 - ServiceManager.getService("wsProcess")- > PRIMEIRO É NECESSÁRIO PEGAR O SERVICO QUE SERA RESPONSAVEL PELA INTEGRACAO DENTRO DO SEU FLUIG , EM PAIENL DE CONTROLE - SERVICOS 
        2 - instantiate() - > O SERVICO RESPOSAVEL POR INTEGRACOES MAIS COMPLEXAS DENTRO DO FLUIG É O WSPROCESS, TAMBÉM EXISTE O WSDATASERVER POREM ELE SERVE PARA CRUD MAIS SIMPLES, ALTERAR, EXCLUIR MOVIMENTOS, REALIZAR UPDATES ETCC
            COMO NESSE CASO É UMA OPERAÇÃO COMPLEXA QUE ENVOLVE RELACIONAMENTOS, FATURAMENTO, GERAÇÃO , TRANSFERENCIA DE DADOS ENTRE OS MOVIMENTOS ETC.. O WSPROCESS EXECUTA ISSO PERFEITAMENTE. 
        3 - IRÁ INSTANCIAR ESSE SERVICO , FAZER UMA ESPÉCIA DE CÓPIA DA CLASSE WSPROCESS (servico.instantiate("com.totvs.WsProcess"))
        4 - getRMIwsProcess() -> TEM ACESSO AOS METODOS DA CLASSE INTANCIADA 
        5 - properties -> INFORMACOES PARA AUTORIZACAO DO USO DO SERVICO DENTRO DO SERVIDOR DO RM, PRINCIPALMENTE O USUARIO E SENHA 
            E, INDISCUTIVELMENTE, UM TIMEOUT BOM, POIS, ISSO PODE IMPEDIR A EXECUSAO DA ATIVIDADE.
        6- getCustomClient() - > PASSAR AS INFORMACOES DE AUTORIZACOES E OS METODOS DA CLASSE INTANCIADA 
        7- executeWithParams() - > Metodo para faturar movimentos , passando o server name e o corpo XML -> executeWithParams("MovFaturamentoProc", xmlParams)

        */
        var servico = ServiceManager.getService("wsProcess");
        var instancia = servico.instantiate("com.totvs.WsProcess");
        var ws = instancia.getRMIwsProcess();
        var properties = {};
        properties['basic.authorization'] = 'true';
        properties['basic.authorization.username'] = usuario_rm;
        properties['basic.authorization.password'] = senha_rm;
        properties['disable.chunking'] = 'true';
        properties['log.soap.messages'] = 'true';
        properties['receive.timeout'] = '180000';

        var authService = servico.getCustomClient(ws, properties, []);

        log.info("### Servico OK, executando faturamento IDMOV=" + idMov);

        var xmlParams =
            '<MovFaturamentoProcParams>' +
            '<movCopiaFatPar>' +
            '<CodColigada>' + codColigada + '</CodColigada>' +
            '<CodSistema>T</CodSistema>' +
            '<CodTmvDestino>2.2.01</CodTmvDestino>' +
            '<CodTmvOrigem>2.1.02</CodTmvOrigem>' +
            '<CodUsuario>fluig</CodUsuario>' +
            '<GrupoFaturamento></GrupoFaturamento>' +
            '<IdExercicioFiscal>' + codigoExercicioFiscal + '</IdExercicioFiscal>' +
            '<IdMov>' +
            '<int>' + idMov + '</int>' +
            '</IdMov>' +
            '<TipoFaturamento>0</TipoFaturamento>' +
            '<dataBase>' + today + '</dataBase>' +
            '<dataEmissao/>' +
            '<dataSaida/>' +
            '<efeitoPedidoFatAutomatico>1</efeitoPedidoFatAutomatico>' +
            '<listaMovItemFatAutomatico/>' +
            '<numeroMov></numeroMov>' +
            '<realizaBaixaPedido>true</realizaBaixaPedido>' +
            '</movCopiaFatPar>' +
            '</MovFaturamentoProcParams>';

        var resp = authService.executeWithParams("MovFaturamentoProc", xmlParams);



    } catch (e) {
        log.error("### Erro: " + e);
        throw e;
    }



    try {


        var c1 = DatasetFactory.createConstraint("IDMOV", idMov, idMov, ConstraintType.MUST);
        var c2 = DatasetFactory.createConstraint("CODCOLIGADA", codColigada, codColigada, ConstraintType.MUST);


        var dataset = DatasetFactory.getDataset("G12-MOVIMENTOS-2102", null, [c2, c1], null);

        if (dataset.rowsCount == 0) throw "[G12-MOVIMENTO 2.1.02 FATURAMENTO] - Nenhum registro encontrado no movimento 2.1.02: " + idMov;

        if (dataset != null && dataset.rowsCount > 0) {
            hAPI.setCardValue("historico2201", dataset.getValue(0, "IDMOV"));
            hAPI.setCardValue("numeroIdmov2201", dataset.getValue(0, "IDMOV"));
            hAPI.setCardValue("numeroMov", dataset.getValue(0, "NUMERO_MOVIMENTO"));

        }


    } catch (error) {
        throw "[G12-MOVIMENTO-2201] - Error ao tentar buscar o movimento 2.2.01 gerado pelo faturamento do RPS: " + error;
    }


    try {
        var c1 = DatasetFactory.createConstraint("IDMOV", idMov, idMov, ConstraintType.MUST);
        var c2 = DatasetFactory.createConstraint("CODCOLIGADA", codColigada, codColigada, ConstraintType.MUST);


        var dataset = DatasetFactory.getDataset("G12-INFO-NFSE", null, [c2, c1], null);

        if (dataset.rowsCount == 0) throw "[G12-INFO-NFSE] - Nenhum registro de NFSE encontrado para o movimento 2.1.02: " + idMov;

        if (dataset != null && dataset.rowsCount > 0) {
            hAPI.setCardValue("codigoVerificacao", dataset.getValue(0, "CODIGO_VERIFICACAO"));
            hAPI.setCardValue("dataEmissao", dataset.getValue(0, "DATA_EMISSAO"));
            hAPI.setCardValue("dataAutorizacao", dataset.getValue(0, "DATA_AUTORIZACAO"));
            hAPI.setCardValue("numeroNotas", dataset.getValue(0, "NUMERO_NFSE"));

        }


    } catch (error) {
        throw "[G12-INFO-NFSE] - Error ao tentar buscar as informações da NFSE do movimento 2.1.02: " + error;
    }



}


function getConstante(param) {
    var aConstraint = [];
    aConstraint.push(DatasetFactory.createConstraint('id', param, param, ConstraintType.MUST));
    var oConstantes = DatasetFactory.getDataset('ds_Constantes', null, null, null);
    for (var i = 0; i < oConstantes.rowsCount; i++) {
        if (oConstantes.getValue(i, "id").trim() == param.trim()) {
            return oConstantes.getValue(i, "Valor").trim();
        }
    }
    return '0';
}

function servicetask30(attempt, message) {
	try {
		Cancelamento();
	} catch (e) {
		throw "servicetask30 " + e;
	}
}

function Cancelamento() {
	try {
		var usuario = getAccess()[0];
		var pass = getAccess()[1];
		var senha = new java.lang.String(pass);

		log.info("USUARIO LOGADO PARA CANCELAMENTO - > " + usuario)
		log.info("SENHA LOGADA PARA CANCELAMENTO - > " + senha)

		var codColigada = hAPI.getCardValue("CodColigada");
		var idMov = hAPI.getCardValue("IdMov");
		var numeroMov = hAPI.getCardValue("numeroMov");

		log.info("========== G12 servicetask30 - INICIO ==========");
		log.info(">> codColigada : [" + codColigada + "]");
		log.info(">> idMov       : [" + idMov + "]");
		log.info(">> numeroMov   : [" + numeroMov + "]");
		log.info(">> usuario     : [" + usuario + "]");

		var hoje = new java.text.SimpleDateFormat("dd/MM/yyyy")
			.format(new java.util.Date());


		var XML = "<MovCancelMovProcParams>";
		XML += "<MovimentosACancelar>";
		XML += "<MovimentosCancelar>";
		XML += "<ApagarMovRelac>false</ApagarMovRelac>";
		XML += "<CancelarMovimentosGeradosSimultFaturamento>false</CancelarMovimentosGeradosSimultFaturamento>";
		XML += "<CancelarMovimentosGeradosSimultReabriCotacao>false</CancelarMovimentosGeradosSimultReabriCotacao>";
		XML += "<CodColigada>" + codColigada + "</CodColigada>";
		XML += "<CodSistemaLogado>T</CodSistemaLogado>";
		XML += "<CodUsuarioLogado>fluig</CodUsuarioLogado>";
		XML += ValidaCampo("DataCancelamento", hoje);
		XML += "<ExcluirItensDaCotacao>false</ExcluirItensDaCotacao>";
		XML += ValidaCampo("IdMov", idMov);
		XML += ValidaCampo("MotivoCancelamento", "Movimento Cancelado por WorkFlow Fluig");
		XML += ValidaCampo("NumeroMov", numeroMov);
		XML += "</MovimentosCancelar>";
		XML += "</MovimentosACancelar>";
		XML += "</MovCancelMovProcParams>";

		log.info(">> XML enviado : [" + XML + "]");

		var NOME_SERVICO = "wsProcess";
		var CAMINHO_SERVICO = "com.totvs.WsProcess";
		var servico = ServiceManager.getServiceInstance(NOME_SERVICO);
		var serviceHelper = servico.getBean();
		var instancia = servico.instantiate(CAMINHO_SERVICO);
		var ws = instancia.getRMIwsProcess();
		var authenticatedService = serviceHelper.getBasicAuthenticatedClient(ws, "com.totvs.IwsProcess", usuario, senha);

		log.info(">> Chamando RM - MovCancelMovProc...");
		var response = authenticatedService.executeWithParams("MovCancelMovProc", XML);
		log.info(">> Response RM completo : [" + response + "]");


		log.warn("TIPO RESPONSE: " + typeof response);
		log.warn("RESPONSE RAW: " + response);

		if (response != null && (
			response.indexOf("===") != -1 ||
			response.indexOf("System.Exception") != -1 ||
			response.indexOf("Exception") != -1 ||
			response.indexOf("erro") != -1 ||
			response.indexOf("Erro") != -1
		)) {
			log.error(">> ERRO do RM detectado: [" + response + "]");
			throw "Erro RM: " + response;
		}


		log.info(">> Cancelamento executado com sucesso");
		log.info("========== G12 servicetask30 - FIM ==========");

		var dataset = DatasetBuilder.newDataset();
		dataset.addColumn("result");
		dataset.addRow(new Array(response));
		return dataset;

	} catch (e) {
		log.error(">> EXCECAO: [" + e.toString() + "]");
		return getDatasetError("ERRO:" + e.toString());
	}
}

function ValidaCampo(campo, valor) {
	if ((valor != null) && (valor != "")) {
		return "<" + campo + ">" + valor + "</" + campo + ">";
	} else {
		log.warn(">> Campo [" + campo + "] vazio - ignorado no XML");
		return "";
	}
}

function getAccess() {
	try {
		var response = new Array();
		var dataset = DatasetFactory.getDataset("dsTBCConnector", null, null, null);
		var u = dataset.getValue(0, "user");
		var p = dataset.getValue(0, "pass");
		log.info(">> getAccess: usuario [" + u + "]");
		response.push(u, p);
		return response;
	} catch (e) {
		throw "getAccess / " + e.toString();
	}
}

function getDatasetError(exception) {
	var dtsError = DatasetBuilder.newDataset();
	dtsError.addColumn("ERROR");
	dtsError.addRow([exception.toString()]);
	return dtsError;
}

function servicetask180(attempt, message) {

    /** * AUTHOR: ENOS DESENVOLVEDOR FLUIG/FULL STACK * CRIADO EM: 06/07/2026 * PROPOSITO: ALTERAR O CAMPO DE CNO DENTRO DO PROJETO NO RM PARA ENVIAR PARA PREFEITURA DE JOAO PESSOA VALIDAR DURANTE A TRANSMISSÃO DA NOTA */
    var codColigada = hAPI.getCardValue("CodColigada");
    var idPrj = hAPI.getCardValue("idprj");
    var cnopb = hAPI.getCardValue("CNOPB");
    var codFilial = hAPI.getCardValue("filial");

    log.info("### INICIANDO SERVIÇO DE ATUALIZAÇÃO DE CNO PB NO RM ###");

    var usuario_rm = getConstante("rm_usuario");
    var senha_rm = getConstante("rm_senha");

    log.info("CODCOLIGADA: " + codColigada + " | IDPRJ: " + idPrj + " | CNOPB: " + cnopb + " | CODFILIAL: " + codFilial);

    try { /* */ var servico = ServiceManager.getService("wsDataServer");
        var instancia = servico.instantiate("com.totvs.WsDataServer");
        var ws = instancia.getRMIwsDataServer();
        var properties = {};
        properties['basic.authorization'] = 'true';
        properties['basic.authorization.username'] = usuario_rm;
        properties['basic.authorization.password'] = senha_rm;
        properties['disable.chunking'] = 'true';
        properties['log.soap.messages'] = 'true';
        properties['receive.timeout'] = '180000';

        var authService = servico.getCustomClient(ws, properties, []);

        var contexto = "CODCOLIGADA=" + codColigada + ";CODFILIAL=" + codFilial + ";CODSISTEMA=T;CODUSUARIO=fluig";

        log.info("### Servico OK, executando atualização de nota fiscal");


        if (codColigada == 2) {
            // XML PARA ATUALIZAR O CNO NO LUGAR DO CNPJ - PARAMETRIZACAO ERRADA NO MOMENTO 
            var xmlParams =
                "<PrjPrj>" +
                "<MPrj>" +
                "<CODCOLIGADA>" + codColigada + "</CODCOLIGADA>" +
                "<IDPRJ>" + idPrj + "</IDPRJ>" +
                "<CGC>" + cnopb + "</CGC>" +
                "</MPrj>" +
                "</PrjPrj>";

            log.info("G12 XML ENVIADO PARA ATUALIZAR CNO PB- > " + xmlParams);

            var resp = authService.saveRecord("PrjPrjData", xmlParams, contexto);

            log.info("G12 ATUALIZAR CNO PB - INFORMACAO RETORNADA DO RM " + resp);

            if (resp && String(resp).indexOf("Exception") !== -1) { throw new Error("Erro retornado pelo RM: " + resp); }
            if (resp && String(resp).indexOf("Error") !== -1) { throw new Error("Erro retornado pelo RM: " + resp); }

        } else {

            //  XML PARA ATUALIZAR O CNO NO LUGAR CORRETO DO PROJETO NO RM
            var xmlParams =
                "<PrjPrj>" +
                "<MPrj>" +
                "<CODCOLIGADA>" + codColigada + "</CODCOLIGADA>" +
                "<IDPRJ>" + idPrj + "</IDPRJ>" +
                "<CNOPRJ>" + cnopb + "</CNOPRJ>" +
                "</MPrj>" +
                "</PrjPrj>";

            log.info("G12 XML ENVIADO PARA ATUALIZAR CNO PB- > " + xmlParams);

            var resp = authService.saveRecord("PrjPrjData", xmlParams, contexto);

            log.info("G12 ATUALIZAR CNO PB - INFORMACAO RETORNADA DO RM " + resp);

            if (resp && String(resp).indexOf("Exception") !== -1) { throw new Error("Erro retornado pelo RM: " + resp); }
            if (resp && String(resp).indexOf("Error") !== -1) { throw new Error("Erro retornado pelo RM: " + resp); }
        }


    }
    catch (e) { log.error("### Erro: " + e); throw e; }
}


function getConstante(param) {
    var aConstraint = [];
    aConstraint.push(DatasetFactory.createConstraint('id', param, param, ConstraintType.MUST));
    var oConstantes = DatasetFactory.getDataset('ds_Constantes', null, null, null);
    for (var i = 0; i < oConstantes.rowsCount; i++) {
        if (oConstantes.getValue(i, "id").trim() == param.trim()) {
            return oConstantes.getValue(i, "Valor").trim();
        }
    }
    return '0';
}

function servicetask71(attempt, message) {
    /**
     * AUTHOR: ENOS DESENVOLVEDOR FLUIG/FULL STACK 
     * CRIADO EM: 29/05/2026
     * PROPOSITO: FATURAR OS MOVIMENTOS DE VENDAS DO TIPO 2.1.01 , CRIAR MOVIMENTO 2.1.02 E GERAR O RELACIONAMENTO ENTRE ELES DENTRO DO RM 
     * PUXAR OS DADOS DE TRIBUTACAO DO MOVIMENTO 2.1.02 PARA ATUALIZAR DENTRO DA TAELA DE IMPOSTOS DO FORMULARIO
    */



    var codColigada = hAPI.getCardValue("CodColigada");
    var idMov = hAPI.getCardValue("IdMov");
    var municipio = hAPI.getCardValue("cidade_projeto");
    var idmovMovimento02;
    var codFilial = hAPI.getCardValue("filial");
    var today = new java.text.SimpleDateFormat("yyyy-MM-dd").format(new java.util.Date());
    var idprj = hAPI.getCardValue("idprj");
    var idContrato = hAPI.getCardValue("idContrato");
    var exercicioFiscal;


    var usuario_rm = getConstante("rm_usuario");
    var senha_rm = getConstante("rm_senha");



    try {
        var c1 = DatasetFactory.createConstraint("CODCOLIGADA", codColigada, codColigada, ConstraintType.MUST);

        var dataset = DatasetFactory.getDataset("G12-EXERCICIO-FISCAL", null, [c1], null);


        if (dataset == null || dataset.rowsCount == 0) {
            log.warn("[G12-service-task71] Nenhum Exercicio fiscal retornado." + " CodColigada=" + codColigada);
            return;
        }


        exercicioFiscal = safe(dataset.getValue(0, "ID_EXERCICIO"));
        hAPI.setCardValue("exercicioFiscal", exercicioFiscal);





    } catch (error) {
        log.error("### Erro ao carregar o exercicio fiscal da coligada em questao - > : " + error);
        throw error;

    }


    log.info("EXERCICIO FISCAL ENCONTRADO - > " + exercicioFiscal);
    log.info("IDMOV ENCONTRADO - > " + idMov);
    log.info("CODCOLIGADA ENTONTRADA PARA O XMl DE FATURAMENTO - > " + codColigada);





    try {

        /* 
        AQUI VAI ACONTECER A MÁGICA DA INTEGRACAO 
        1 - ServiceManager.getService("wsProcess")- > PRIMEIRO É NECESSÁRIO PEGAR O SERVICO QUE SERA RESPONSAVEL PELA INTEGRACAO DENTRO DO SEU FLUIG , EM PAIENL DE CONTROLE - SERVICOS 
        2 - instantiate() - > O SERVICO RESPOSAVEL POR INTEGRACOES MAIS COMPLEXAS DENTRO DO FLUIG É O WSPROCESS, TAMBÉM EXISTE O WSDATASERVER POREM ELE SERVE PARA CRUD MAIS SIMPLES, ALTERAR, EXCLUIR MOVIMENTOS, REALIZAR UPDATES ETCC
            COMO NESSE CASO É UMA OPERAÇÃO COMPLEXA QUE ENVOLVE RELACIONAMENTOS, FATURAMENTO, GERAÇÃO , TRANSFERENCIA DE DADOS ENTRE OS MOVIMENTOS ETC.. O WSPROCESS EXECUTA ISSO PERFEITAMENTE. 
        3 - IRÁ INSTANCIAR ESSE SERVICO , FAZER UMA ESPÉCIA DE CÓPIA DA CLASSE WSPROCESS (servico.instantiate("com.totvs.WsProcess"))
        4 - getRMIwsProcess() -> TEM ACESSO AOS METODOS DA CLASSE INTANCIADA 
        5 - properties -> INFORMACOES PARA AUTORIZACAO DO USO DO SERVICO DENTRO DO SERVIDOR DO RM, PRINCIPALMENTE O USUARIO E SENHA 
            E, INDISCUTIVELMENTE, UM TIMEOUT BOM, POIS, ISSO PODE IMPEDIR A EXECUSAO DA ATIVIDADE.
        6- getCustomClient() - > PASSAR AS INFORMACOES DE AUTORIZACOES E OS METODOS DA CLASSE INTANCIADA 
        7- executeWithParams() - > Metodo para faturar movimentos , passando o server name e o corpo XML -> executeWithParams("MovFaturamentoProc", xmlParams)

        */
        var servico = ServiceManager.getService("wsProcess");
        var instancia = servico.instantiate("com.totvs.WsProcess");
        var ws = instancia.getRMIwsProcess();
        var properties = {};
        properties['basic.authorization'] = 'true';
        properties['basic.authorization.username'] = usuario_rm;
        properties['basic.authorization.password'] = senha_rm;
        properties['disable.chunking'] = 'true';
        properties['log.soap.messages'] = 'true';
        properties['receive.timeout'] = '180000';

        var authService = servico.getCustomClient(ws, properties, []);

        log.info("### Servico OK, executando faturamento IDMOV=" + idMov);

        var xmlParams =
            '<MovFaturamentoProcParams>' +
            '<movCopiaFatPar>' +
            '<CodColigada>' + codColigada + '</CodColigada>' +
            '<CodSistema>T</CodSistema>' +
            '<CodTmvDestino>2.1.02</CodTmvDestino>' +
